defmodule XipeTotecWithoutNix.Application do
  # This repository's own. Upstream's main.exs loads every file with
  # Code.require_file, and with them the plugins its compiled files required
  # (lib/xipe_totec_without_nix/plugins.ex, generated by sync/transform.exs);
  # here they are loaded when the application starts. Nothing else is started:
  # the CLI (XipeTotec.CLI.main/1, through bin/xipe) does the rest, as main.exs did.
  @moduledoc false
  use Application

  @impl true
  def start(_type, _args) do
    :ok = XipeTotecWithoutNix.Plugins.load()
    Supervisor.start_link([], strategy: :one_for_one, name: XipeTotecWithoutNix.Supervisor)
  end
end
